	@Test
	void requestCancellationStopsInFlightBareRowBeforeEmission() throws Exception {
		ControlledPlan plan = new ControlledPlan();
		NativeLmdbQuerySource source = new StubSource();
		NativeSlotLayout layout = layout();
		NativeBareRowsStep step = NativeRowsStep.bareFragment(source, plan, layout, new int[] { 0 },
				new String[] { "value" }, false, null, null, null);
		QueryBindingSet base = new QueryBindingSet();
		base.addBinding("outer", SimpleValueFactory.getInstance().createIRI("urn:cancellation:outer"));
		CloseableIteration<BindingSet> iteration = step.evaluate(base);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<Boolean> worker = executor.submit(iteration::hasNext);

		try {
			assertThat(plan.rowEntered.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS))
					.as("the bare-row worker must enter its cursor before cancellation")
					.isTrue();
			assertThat(iteration).isInstanceOf(CooperativeCancellation.class);
			assertThat(((CooperativeCancellation) iteration).requestCancellation()).isTrue();
			plan.releaseRow.countDown();

			assertThat(worker.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS))
					.as("a row returned after cancellation must not be emitted")
					.isFalse();
			assertThat(plan.nextCalls).hasValue(1);
			assertThat(plan.closeCalls).hasValue(1);
		} finally {
			plan.releaseRow.countDown();
			iteration.close();
			executor.shutdownNow();
			executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
	}

