	@Test
	void requestCancellationStopsInFlightOrderedMaterializationBeforeEmission() throws Exception {
		ControlledPlan plan = new ControlledPlan();
		NativeLmdbQuerySource source = new StubSource();
		NativeSlotLayout layout = layout();
		NativeRowsStep step = new NativeRowsStep(source, plan, layout, new int[] { 0 }, new String[] { "value" },
				false, new int[] { 0 }, new boolean[] { true }, 0L, -1L, false, null, null, null, Set.of(), null,
				null);
		CloseableIteration<BindingSet> iteration = step.evaluate(EmptyBindingSet.getInstance());
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<Boolean> worker = executor.submit(iteration::hasNext);

		try {
			assertThat(plan.rowEntered.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS))
					.as("the ordered materializer must enter its cursor before cancellation")
					.isTrue();
			assertThat(iteration).isInstanceOf(CooperativeCancellation.class);
			assertThat(((CooperativeCancellation) iteration).requestCancellation()).isTrue();
			plan.releaseRow.countDown();

			assertThat(worker.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS))
					.as("an ordered row returned after cancellation must not reach the materialized result")
					.isFalse();
			assertThat(plan.nextCalls).hasValue(1);
			assertThat(plan.closeCalls).hasValue(1);
		} finally {
			plan.releaseRow.countDown();
			iteration.close();
			executor.shutdownNow();
			executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
	}

	@Test
	@ResourceLock(Resources.SYSTEM_PROPERTIES)
	void requestCancellationStopsOrderedEagerPostSortProjectionBeforeEmission() throws Exception {
		String previousLazyResults = System.getProperty(NativeProjectedBindingSet.ENABLED_PROPERTY);
		System.setProperty(NativeProjectedBindingSet.ENABLED_PROPERTY, "false");
		try {
			CountDownLatch projectionEntered = new CountDownLatch(1);
			CountDownLatch releaseProjection = new CountDownLatch(1);
			NativeLmdbQuerySource source = new SyntheticValueSource(
					new StubSource(projectionEntered, releaseProjection), PlanValueCatalog.EMPTY);
			NativeSlotLayout layout = layout();
			SlotPlan plan = new SlotPlan() {
				@Override
				public RowCursor open(RowState row) {
					return new RowCursor() {
						private boolean emitted;

						@Override
						public boolean next() {
							if (emitted) {
								return false;
							}
							emitted = true;
							row.bind(0, 1L);
							return true;
						}

						@Override
						public void close() {
						}
					};
				}

				@Override
				public long producedMask() {
					return 1L;
				}
			};
			NativeRowsStep step = new NativeRowsStep(source, plan, layout, new int[] { 0 }, new String[] { "value" },
					true, new int[] { 0 }, new boolean[] { true }, 0L, -1L, false, null, null, null, Set.of(), null,
					null);
			CloseableIteration<BindingSet> iteration = step.evaluate(EmptyBindingSet.getInstance());
			ExecutorService executor = Executors.newSingleThreadExecutor();
			Future<Boolean> worker = executor.submit(iteration::hasNext);

			try {
				assertThat(projectionEntered.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS))
						.as("the eager ordered worker must enter post-sort projection before cancellation")
						.isTrue();
				assertThat(((CooperativeCancellation) iteration).requestCancellation()).isTrue();
				releaseProjection.countDown();

				assertThat(worker.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS))
						.as("a row projected after cancellation must not reach the result")
						.isFalse();
			} finally {
				releaseProjection.countDown();
				iteration.close();
				executor.shutdownNow();
				executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			}
		} finally {
			if (previousLazyResults == null) {
				System.clearProperty(NativeProjectedBindingSet.ENABLED_PROPERTY);
			} else {
				System.setProperty(NativeProjectedBindingSet.ENABLED_PROPERTY, previousLazyResults);
			}
		}
	}

	@Test
	void generatedKernelContextPollsSharedRowCancellation() {
		NativeLmdbQuerySource source = new StubSource();
		RowState row = new RowState(source, layout(), EmptyBindingSet.getInstance());
		LmdbNativeKernelBindings bindings = new LmdbNativeKernelBindings(
				new LmdbNativeKernelBindings.AdjacencyRequest[0], new long[0], new int[0],
				new LmdbNativeKernelBindings.DomainRequest[0], new LmdbNativeKernelBindings.FilterHook[0], new int[0],
				List.of());

		KernelContext context = bindings.context(new NativeLmdbQuerySource.NativeAdjacency[0],
				new LmdbNativeKernelBindings.BoundDomains(new long[0][], new int[0], new int[0]), row, null);
		assertThat(context.cancellation)
				.as("normal generated kernels must poll the evaluation token even outside a probe deadline")
				.isNotNull();
		assertThat(context.cancellation.cancelled()).isFalse();
		row.cancellation.requestCancellation();
		assertThat(context.cancellation.cancelled()).isTrue();
	}

	@Test
	void requestCancellationStopsWorkerWaitingForMorsel() throws Exception {
		RowState row = new RowState(new StubSource(), layout(), EmptyBindingSet.getInstance());
		PatternPlan root = new PatternPlan(Term.slot(0), Term.constant(7L), Term.unbound(), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 1D);
		CountDownLatch queuePolled = new CountDownLatch(1);
		ArrayBlockingQueue<LmdbNativeExchange.Morsel> queue = new ArrayBlockingQueue<>(1) {
			private static final long serialVersionUID = 1L;

			@Override
			public LmdbNativeExchange.Morsel poll(long timeout, TimeUnit unit) throws InterruptedException {
				queuePolled.countDown();
				return super.poll(timeout, unit);
			}
		};
		AtomicBoolean workerCancelled = new AtomicBoolean();
		LmdbNativeExchange.MorselCursor cursor = new LmdbNativeExchange.MorselCursor(queue, root, row,
				new AtomicReference<>(), workerCancelled);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<Boolean> worker = executor.submit(cursor::next);

		try {
			assertThat(queuePolled.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS)).isTrue();
			row.cancellation.requestCancellation();
			assertThat(worker.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS))
					.as("an idle parallel worker must observe the shared evaluation token")
					.isFalse();
		} finally {
			workerCancelled.set(true);
			cursor.close();
			executor.shutdownNow();
			executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
	}

	private static NativeSlotLayout layout() {
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("value", 0), null);
		layout.freeze(List.of("value"));
		return layout;
	}

	private static KernelPlan boundPlan(RowState row, SlotPlan nested) {
		LmdbNativeKernelBindings bindings = new LmdbNativeKernelBindings(
				new LmdbNativeKernelBindings.AdjacencyRequest[0], new long[0], new int[0],
				new LmdbNativeKernelBindings.DomainRequest[0], new LmdbNativeKernelBindings.FilterHook[0],
				new int[0], List.of(), new StatementOrder[0],
				new LmdbNativeKernelBindings.PlanRequest[] {
						new LmdbNativeKernelBindings.PlanRequest(nested, new int[] { 0 }) },
				null, false, 16);
		return bindings.context(new NativeLmdbQuerySource.NativeAdjacency[0],
				new LmdbNativeKernelBindings.BoundDomains(new long[0][], new int[0], new int[0]), row,
				null).plans[0];
	}

	private static PatternPlan partialBatchPattern() {
		return new PatternPlan(Term.unbound(), Term.unbound(), Term.unbound(), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 2D);
	}

	private static final class CancellationProbePlan implements SlotPlan {
		private final AtomicInteger nextCalls = new AtomicInteger();
		private final AtomicInteger closeCalls = new AtomicInteger();

		@Override
		public RowCursor open(RowState row) {
			return new RowCursor() {
				@Override
				public boolean next() {
					nextCalls.incrementAndGet();
					throw new AssertionError("cancelled bound plan advanced before its first row");
				}

				@Override
				public void close() {
					closeCalls.incrementAndGet();
				}
			};
		}

		@Override
		public long producedMask() {
			return 1L;
		}
	}

	private static final class PartialBatchPlan {
		private final CountDownLatch secondEntered = new CountDownLatch(1);
		private final CountDownLatch releaseSecond = new CountDownLatch(1);
		private final AtomicInteger nextCalls = new AtomicInteger();
		private final AtomicInteger closeCalls = new AtomicInteger();

		private RecordIterator open() {
			return new RecordIterator() {
				@Override
				public long[] next() {
					int call = nextCalls.incrementAndGet();
					if (call == 1) {
						return new long[] { 1L, 1L, 2L, 0L };
					}
					if (call == 2) {
						secondEntered.countDown();
						await(releaseSecond);
						return new long[] { 1L, 1L, 4L, 0L };
					}
					throw new AssertionError("bound plan advanced beyond cancelled partial batch");
				}

				@Override
				public void close() {
					closeCalls.incrementAndGet();
				}
			};
		}
	}

	private static final class PartialBatchSource extends StubSource {
		private final PartialBatchPlan plan;

		private PartialBatchSource(PartialBatchPlan plan) {
			this.plan = plan;
		}

		@Override
		public RecordIterator statements(long subj, long pred, long obj, long context) {
			return plan.open();
		}
	}

	private static final class IOExceptionPlan implements SlotPlan {
		private final IOException scanFailure;
		private final RuntimeException closeFailure;
		private final AtomicInteger closeCalls = new AtomicInteger();

		private IOExceptionPlan(IOException scanFailure, RuntimeException closeFailure) {
			this.scanFailure = scanFailure;
			this.closeFailure = closeFailure;
		}

		@Override
		public RowCursor open(RowState row) {
			return new RowCursor() {
				@Override
				public boolean next() throws IOException {
					throw scanFailure;
				}

				@Override
				public void close() {
					closeCalls.incrementAndGet();
					throw closeFailure;
				}
			};
		}

		@Override
		public long producedMask() {
			return 1L;
		}
	}

	private static final class ControlledPlan implements SlotPlan {

		private final CountDownLatch rowEntered = new CountDownLatch(1);
		private final CountDownLatch releaseRow = new CountDownLatch(1);
		private final AtomicInteger nextCalls = new AtomicInteger();
		private final AtomicInteger closeCalls = new AtomicInteger();

		@Override
		public RowCursor open(RowState row) {
			return new RowCursor() {
				@Override
				public boolean next() {
					int call = nextCalls.incrementAndGet();
					if (call == 1) {
						rowEntered.countDown();
						await(releaseRow);
						row.bind(0, 1L);
						return true;
					}
					throw new AssertionError("row cursor advanced after cancellation was visible");
				}

				@Override
				public void close() {
					closeCalls.incrementAndGet();
				}
			};
		}

		@Override
		public long producedMask() {
			return 1L;
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			if (!latch.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS)) {
				throw new AssertionError("timed out waiting for controlled row release");
			}
		} catch (InterruptedException e) {
			Thread.currentThread().interrupt();
			throw new AssertionError("row worker interrupted while awaiting release", e);
		}
	}

	private static class StubSource implements NativeLmdbQuerySource {

		private final Object idSpace = new Object();
		private final CountDownLatch projectionEntered;
		private final CountDownLatch releaseProjection;

		private StubSource() {
			this(null, null);
		}

		private StubSource(CountDownLatch projectionEntered, CountDownLatch releaseProjection) {
			this.projectionEntered = projectionEntered;
			this.releaseProjection = releaseProjection;
		}

		@Override
		public long idOf(Value value) {
			return UNKNOWN_ID;
		}

		@Override
		public Value lazyValue(long id) {
			if (projectionEntered != null) {
				projectionEntered.countDown();
				await(releaseProjection);
			}
			return SimpleValueFactory.getInstance().createIRI("urn:cancellation:value:" + id);
		}

		@Override
		public Object idSpace() {
			return idSpace;
		}

		@Override
		public boolean hasStatementsInSource() {
			return false;
		}

		@Override
		public RecordIterator statements(long subj, long pred, long obj, long context) {
			return new RecordIterator() {
				@Override
				public long[] next() {
					return null;
				}

				@Override
				public void close() {
				}
			};
		}

		@Override
		public long count(long subj, long pred, long obj, long context) {
			return 0L;
		}

		@Override
		public boolean has(long subj, long pred, long obj, long context) {
			return false;
		}

		@Override
		public double estimate(long subj, long pred, long obj, long context) {
			return 0D;
		}
	}
